CREATE TABLE public.est_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sheet text NOT NULL CHECK (sheet IN ('employees','documents','leaves','payroll','evaluations')),
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  sort integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.est_records TO authenticated;
GRANT ALL ON public.est_records TO service_role;
ALTER TABLE public.est_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read est" ON public.est_records FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr') OR public.has_role(auth.uid(),'viewer'));
CREATE POLICY "hr writes est" ON public.est_records FOR ALL TO authenticated
  USING (public.has_role(auth.uid(),'hr')) WITH CHECK (public.has_role(auth.uid(),'hr'));
